SELECT *
FROM message_chat
WHERE tenant_id = #{tenantId}
  AND sender_type = #{senderType}
  AND sender_id = #{senderId}
  AND client_message_id = #{clientMessageId}
  AND del_flag = '0'
LIMIT 1

SELECT *
FROM message_chat
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND del_flag = '0'


        AND seq_no > #{afterSeq}
        ORDER BY seq_no ASC



            AND seq_no < #{beforeSeq}

        ORDER BY seq_no DESC


LIMIT #{fetchSize}
